package com.franco.desco.adapter.in.web.campaign;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.campaign.*;import com.franco.desco.application.campaign.port.in.CampaignUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController@RequestMapping("/api/v1/campanias")@Tag(name="Campañas de venta",description="Planificación, activación, cierre y consulta comercial de campañas.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class CampaignController{private final CampaignUseCase u;private final CampaignWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public CampaignController(CampaignUseCase u,CampaignWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_LISTAR')")@Operation(operationId="campaniasListar",summary="Listar campañas")public ResponseEntity<ApiResponse<PageResponse<CampaignResponses.Summary>>>list(@RequestParam(required=false)String estadoProceso,@RequestParam(required=false)Long asociacionId,@RequestParam(required=false)Long empresaCompradoraId,@RequestParam(required=false)LocalDate fechaDesde,@RequestParam(required=false)LocalDate fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,estadoProceso,asociacionId,empresaCompradoraId,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_VER')")@Operation(operationId="campaniasVer",summary="Ver campaña")public ResponseEntity<ApiResponse<CampaignResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new CampaignCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_CREAR')")@Operation(operationId="campaniasCrear",summary="Crear campaña")public ResponseEntity<ApiResponse<CampaignResponses.Created>>create(@Valid@RequestBody CampaignRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new CampaignCommands.Create(q.asociacionId(),q.empresaCompradoraId(),q.codigo(),q.nombre(),q.fechaInicio(),q.fechaFin(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,CampaignResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_EDITAR')")@Operation(operationId="campaniasEditar",summary="Editar campaña")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody CampaignRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new CampaignCommands.Update(id,q.empresaCompradoraId(),q.nombre(),q.fechaInicio(),q.fechaFin(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/activar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_CONFIRMAR') || @permissionGuard.has(authentication,'CAMPANIAS_APROBAR')")@Operation(operationId="campaniasActivar",summary="Activar campaña")public ResponseEntity<ApiResponse<Void>>activate(@PathVariable Long id,@Valid@RequestBody CampaignRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.activate(new CampaignCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cerrar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_CONFIRMAR') || @permissionGuard.has(authentication,'CAMPANIAS_APROBAR')")@Operation(operationId="campaniasCerrar",summary="Cerrar campaña")public ResponseEntity<ApiResponse<Void>>close(@PathVariable Long id,@Valid@RequestBody CampaignRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.close(new CampaignCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cancelar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'CAMPANIAS_RETIRAR')")@Operation(operationId="campaniasCancelar",summary="Cancelar campaña")public ResponseEntity<ApiResponse<Void>>cancel(@PathVariable Long id,@Valid@RequestBody CampaignRequests.Transition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.cancel(new CampaignCommands.Transition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
